"""Money math for billing (pre-FIN-2140: floating-point dollars).

NOTE: allocations here run on float dollars and round each share independently, so the parts do NOT
always sum back to the total -- fractions of a cent are created or destroyed on non-divisible splits.
"""


def to_cents(amount):
    return int(round(float(amount) * 100))


def allocate_evenly(total_cents, n):
    total = int(total_cents)
    n = int(n)
    share = round((total / 100.0) / n, 2)          # float dollars, rounded per share
    return [int(round(share * 100))] * n           # parts may not sum back to total


def allocate_weighted(total_cents, weights):
    total = int(total_cents)
    w = [float(x) for x in weights]
    sw = sum(w)
    return [int(round((total / 100.0) * (x / sw), 2) * 100) for x in w]


def order_total(line_items):
    return int(round(sum(float(u) * int(q) for (u, q) in line_items) * 100))

